      SUBROUTINE ACCMTXCC     CALCULATES THE TRANSFER MATRIX FOR AN ACCELERATOR SECTIONCC     LIST OF COMMON BLOCKSC      INCLUDE 'CONSTS.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM1A.CIN'      INCLUDE 'ELM11.CIN'      INCLUDE 'ELM16B.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'R.CIN'CC     LOCAL VARIABLESCC----------------------------------------------------      IF (NORD1 .LT. 1) GO TO 100      COSPHI = COS(PHASEL)      SINPHI = SIN(PHASEL)      DEE = EGAIN*COSPHI      DUM = EGAIN*SINPHICC     ELECTRONSC      IF (SM .NE. 0.0) GO TO 50      IF (ABS(DEE/RI) .LT. 0.01) THEN        R(1,2) = L*(1.0 - 0.5*DEE/RI + (DEE/RI)**2/3.0)      ELSE        R(1,2) = L*(RI*LOG(1. + DEE/RI)/DEE)      ENDIF      R(2,2) = RI/(RI + DEE)      R(3,4) = R(1,2)      R(4,4) = R(2,2)      IF (WAVEL .NE. 0.) R(6,5) = (DUM/(RI+DEE))*(2.0*PI/WAVEL)      R(6,6) = R(2,2)      RINEW = RI + DEE      PREF = PREF*RINEW/RI      RI = RINEW      GO TO 100CC     PROTONS AND HEAVY IONSC   50 EOLD = SQRT(RI**2 + SM**2)      ENEW = EOLD + DEE      RINEW = SQRT(ENEW**2 - SM**2)      GAMIN = EOLD/SM      BETAIN = RI/EOLD      ETAIN = RI/SM      GAM = ENEW/SM      BETA = RINEW/ENEW      ETAN = RINEW/SM      DGAM = DEE/(SM*L)      DETA = GAM*DGAM/ETAN      DETAIN = GAMIN*DGAM/ETAIN      SQEIN = SQRT(ETAIN)      SQET = SQRT(ETAN)      RETA = SQRT(SQET/SQEIN)      RBETA = BETA/BETAIN      Q = PI*DUM/(L*WAVEL*SM)      TQ = 2.0*Q      QSQ = SQRT(Q)      STQ = SQRT(TQ)      DELG = DEE/SM      FINT = DELG - 0.75*GAMIN*DELG**2/ETAIN**2     1     - 0.25*DELG**3/ETAIN**2 + 0.875*GAMIN**2*DELG**3/ETAIN**4      FINT = FINT/(DGAM*SQRT(ETAIN**3))      FINTA = QSQ*FINT      COSK = COSH(FINTA)      SINK = SINH(FINTA)      FINTB = STQ*FINT      COSL = COS(FINTB)      SINL = SIN(FINTB)      R(1,1) = RETA*COSK - 0.25*DETAIN*SQEIN*RETA*SINK/QSQ      R(1,2) = SQEIN**3*RETA*SINK/QSQ      R(2,1) = 0.25*(DETA*RETA - DETAIN/RETA)*COSK/ETAN     1       + (RETA*QSQ/ETAN     2       - 0.0625*DETA*DETAIN/(RETA*QSQ))*SINK/SQET      R(2,2) = 0.25*SQEIN**3*DETA*RETA*SINK/(QSQ*ETAN)     1       + COSK/RETA**5      R(3,3) = R(1,1)      R(3,4) = R(1,2)      R(4,3) = R(2,1)      R(4,4) = R(2,2)      R(5,5) = RBETA*COSL/RETA**3     1       + 0.75*RBETA*DETAIN*SQEIN*SINL/(RETA*STQ)      R(5,6) = BETA*BETAIN*(0.75*(- DETA/RETA     1       + DETAIN*RETA**3)*COSL     2       + (0.5625*DETA*DETAIN*SQEIN/STQ     3       + STQ/SQET)*SINL/RETA)/TQ      IF (WAVEL .NE. 0.0) THEN        R(6,5) = - SQEIN*STQ*SINL/(BETA*BETAIN*RETA)      ENDIF      R(6,6) = (COSL - 0.75*SQEIN*DETAIN*SINL/STQ)/(RBETA*RETA)      PREF = PREF*RINEW/RI      RI = RINEWC  100 RETURN      END